import { View, Text, TouchableOpacity } from 'react-native'
import { Image } from 'expo-image'
import { defineStyles } from '@/utils/defineStyles'
import { Block } from '../utils/types'
import { colors, Theme, useTheme } from '@/theme'
import { router } from 'expo-router'
import { useState, memo } from 'react'

const DynamicImage = memo(
	({ imageUrl, onPress }: { imageUrl: string; onPress: () => void }) => {
		const [imageSize, setImageSize] = useState({ width: 0, height: 0 })
		const [isLoaded, setIsLoaded] = useState(false)

		const handleLoad = (event: any) => {
			const { width, height } = event.source
			setImageSize({ width, height })
			setIsLoaded(true)
		}

		const displayDimensions = (() => {
			if (!isLoaded || imageSize.width === 0 || imageSize.height === 0) {
				return { width: 200, height: 200 }
			}

			const maxWidth = 250
			const maxHeight = 300

			let displayWidth = imageSize.width
			let displayHeight = imageSize.height

			if (imageSize.width > maxWidth) {
				displayWidth = maxWidth
				displayHeight = (imageSize.height * maxWidth) / imageSize.width
			}

			if (displayHeight > maxHeight) {
				displayHeight = maxHeight
				displayWidth = (imageSize.width * maxHeight) / imageSize.height
			}

			return { width: displayWidth, height: displayHeight }
		})()

		return (
			<TouchableOpacity style={styles.imageContainer} onPress={onPress}>
				<Image
					source={{ uri: imageUrl }}
					style={[styles.image, displayDimensions]}
					contentFit="cover"
					transition={200}
					onLoad={handleLoad}
					cachePolicy="memory-disk"
				/>
			</TouchableOpacity>
		)
	}
)
DynamicImage.displayName = 'DynamicImage'

export const UserMessage = memo(({ block }: { block: Block }) => {
	const { theme } = useTheme()

	const contentParts = (() => {
		if (!('code' in block) || !block.code) {
			return [{ type: 'text', content: '' }]
		}

		const parts = []
		const imageRegex = /!\[([^\]]*)\]\(([^)]+)\)/g
		let lastIndex = 0
		let match

		while ((match = imageRegex.exec(block.code)) !== null) {
			if (match.index > lastIndex) {
				parts.push({
					type: 'text',
					content: block.code.slice(lastIndex, match.index)
				})
			}

			parts.push({
				type: 'image',
				altText: match[1],
				imageUrl: match[2]
			})

			lastIndex = match.index + match[0].length
		}

		if (lastIndex < block.code.length) {
			parts.push({
				type: 'text',
				content: block.code.slice(lastIndex)
			})
		}

		return parts
	})()

	const handleAssetViewPress = (asset: string) => {
		router.push({
			pathname: '/asset-view-modal',
			params: {
				asset
			}
		})
	}

	return (
		<View style={styles.container(theme)}>
			{contentParts.map((part, index) => {
				if (part.type === 'image' && part.imageUrl) {
					return (
						<DynamicImage
							key={index}
							imageUrl={part.imageUrl}
							onPress={() => handleAssetViewPress(part.imageUrl)}
						/>
					)
				} else {
					return (
						<Text key={index} style={styles.text(theme)}>
							{part.content}
						</Text>
					)
				}
			})}
		</View>
	)
})
UserMessage.displayName = 'UserMessage'

const styles = defineStyles({
	container: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[50],
		paddingHorizontal: 20,
		paddingVertical: 16,
		borderRadius: 28,
		alignSelf: 'flex-end',
		marginLeft: 20,
		maxWidth: 280
	}),
	text: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '500',
		color: colors[theme].gray[900],
		lineHeight: 22
	}),
	imageContainer: {
		marginVertical: 8,
		alignSelf: 'flex-start'
	},
	image: {
		borderRadius: 12
	},
	altText: (theme: Theme) => ({
		fontSize: 14,
		color: colors[theme].gray[600],
		marginTop: 8,
		fontStyle: 'italic'
	})
})
